// Validate and normalize input
const input = $input.first().json.body || $input.first().json;

const topicId = input.topic_id || null;
const topicText = input.topic || null;
const depth = input.depth || 'medium';
const focusAreas = input.focus_areas || [];
const callbackWorkflow = input.callback_workflow || null;
const skipCache = input.skip_cache || false;
const maxRefinementRounds = input.max_refinement_rounds || 1;

if (!topicId && !topicText) {
  throw new Error('Must provide either topic_id or topic text');
}

const validDepths = ['light', 'medium', 'deep'];
if (!validDepths.includes(depth)) {
  throw new Error(`Invalid depth: ${depth}. Must be: ${validDepths.join(', ')}`);
}

const queryConfig = {
  light: { count: 3, useBoard: false, maxRefinements: 0 },
  medium: { count: 7, useBoard: false, maxRefinements: 1 },
  deep: { count: 12, useBoard: true, maxRefinements: 2 }
};

const config = queryConfig[depth];

return [{
  json: {
    topic_id: topicId,
    topic: topicText,
    depth: depth,
    query_count: config.count,
    use_board_of_directors: config.useBoard,
    max_refinement_rounds: Math.min(maxRefinementRounds, config.maxRefinements),
    current_refinement_round: 0,
    focus_areas: focusAreas,
    callback_workflow: callbackWorkflow,
    skip_cache: skipCache,
    session_id: `research_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    started_at: new Date().toISOString()
  }
}];

// Extract embedding and prepare cache lookup
const input = $('Validate & Configure').first().json;
const embeddingResponse = $input.first().json;

const embedding = embeddingResponse.data?.[0]?.embedding || [];

if (embedding.length === 0) {
  console.warn('Failed to generate embedding, skipping cache');
}

return [{
  json: {
    ...input,
    query_embedding: embedding,
    embedding_model: 'text-embedding-3-small',
    embedding_dimensions: embedding.length
  }
}];

const fs = require('fs');
const path = require('path');
const researchDir = 'C:/dev/production_line/research';

try {
  if (!fs.existsSync(researchDir)) {
    return [{ json: { _empty: true } }];
  }
  const files = fs.readdirSync(researchDir).filter(f => f.endsWith('.json'));
  if (files.length === 0) {
    return [{ json: { _empty: true } }];
  }
  const results = [];
  for (const file of files.slice(-10)) {
    const content = JSON.parse(fs.readFileSync(path.join(researchDir, file), 'utf8'));
    results.push({ json: content });
  }
  return results;
} catch (err) {
  return [{ json: { _empty: true, error: err.message } }];
}

// Calculate cosine similarity between query and cached research
const inputData = $('Extract Embedding').first().json;
const queryEmbedding = inputData.query_embedding;
const cachedRecords = $input.all().map(item => item.json);

// Cosine similarity function
function cosineSimilarity(a, b) {
  if (!a || !b || a.length !== b.length) return 0;
  let dotProduct = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dotProduct += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
}

// Find best matching cached research
let bestMatch = null;
let bestSimilarity = 0;
const SIMILARITY_THRESHOLD = 0.85;

for (const record of cachedRecords) {
  try {
    const cachedEmbedding = JSON.parse(record.Embedding || '[]');
    const similarity = cosineSimilarity(queryEmbedding, cachedEmbedding);

    if (similarity > bestSimilarity && similarity >= SIMILARITY_THRESHOLD) {
      bestSimilarity = similarity;
      bestMatch = {
        record_id: record.id,
        topic: record['Topic Text'],
        summary: record.Summary,
        insights: record.Insights,
        quality_score: record['Quality Score'],
        similarity: similarity,
        created: record.Created
      };
    }
  } catch (e) {
    console.warn('Failed to parse cached embedding:', e);
  }
}

return [{
  json: {
    ...inputData,
    cache_hit: bestMatch !== null,
    cached_research: bestMatch,
    cache_similarity: bestSimilarity,
    cache_threshold: SIMILARITY_THRESHOLD
  }
}];

// No cache check - pass through
const input = $('Extract Embedding').first().json;

return [{
  json: {
    ...input,
    cache_hit: false,
    cached_research: null,
    cache_similarity: 0,
    cache_threshold: 0.85
  }
}];

// Pass through whichever input has data
const items = $input.all();
if (items.length === 0 || (items.length === 1 && items[0].json._empty)) {
  throw new Error('No data received from cache paths');
}
return items.filter(item => !item.json._empty);

// Generate research queries with cache awareness
const input = $input.first().json;
const topic = input.topic;
const depth = input.depth;
const focusAreas = input.focus_areas || [];
const cacheHit = input.cache_hit;
const cachedResearch = input.cached_research;
const refinementRound = input.current_refinement_round || 0;
const refinementQuestions = input.refinement_questions || [];

// If this is a refinement round, use critic's questions
if (refinementRound > 0 && refinementQuestions.length > 0) {
  return refinementQuestions.map((q, index) => ({
    json: {
      ...input,
      current_query: q.question,
      query_index: index,
      query_category: q.category || 'refinement',
      total_queries: refinementQuestions.length,
      is_refinement: true
    }
  }));
}

// Base query templates
const queryTemplates = {
  core: [
    { query: `${topic} comprehensive overview 2024`, category: 'overview' },
    { query: `${topic} key statistics data research`, category: 'statistics' },
    { query: `${topic} common problems challenges solutions`, category: 'problems' }
  ],
  extended: [
    { query: `${topic} expert opinions industry leaders`, category: 'expert' },
    { query: `${topic} case studies real examples success`, category: 'examples' },
    { query: `${topic} best practices methodology framework`, category: 'framework' },
    { query: `${topic} tools software platforms comparison`, category: 'tools' }
  ],
  deep: [
    { query: `${topic} historical evolution timeline origin`, category: 'history' },
    { query: `${topic} controversies criticism failures lessons`, category: 'skeptic' },
    { query: `${topic} future predictions trends 2025 2030`, category: 'future' },
    { query: `${topic} academic research scientific studies`, category: 'academic' },
    { query: `${topic} market size growth investment funding`, category: 'market' }
  ]
};

// Build query list based on depth
let queries = [...queryTemplates.core];
if (depth === 'medium' || depth === 'deep') {
  queries = [...queries, ...queryTemplates.extended];
}
if (depth === 'deep') {
  queries = [...queries, ...queryTemplates.deep];
}

// Add focus area queries
focusAreas.forEach(area => {
  queries.push({ 
    query: `${topic} ${area} detailed analysis`, 
    category: 'focus' 
  });
});

// If cache hit, add delta queries
if (cacheHit && cachedResearch) {
  queries.push({
    query: `${topic} latest news developments past 30 days`,
    category: 'delta'
  });
  queries.push({
    query: `${topic} recent announcements updates 2024`,
    category: 'delta'
  });
}

// Return each query as separate item
return queries.map((q, index) => ({
  json: {
    ...input,
    current_query: q.query,
    query_index: index,
    query_category: q.category,
    total_queries: queries.length,
    is_refinement: false
  }
}));

