// Parse response and score source authority
const input = $input.item.json;
const queryData = $('Generate Research Queries').item.json;

// Parse Perplexity response
let content = '';
let citations = [];

if (input.choices && input.choices[0]) {
  content = input.choices[0].message?.content || '';
}
if (input.citations) {
  citations = input.citations;
}

// Authority scoring rules
const HIGH_AUTHORITY_DOMAINS = [
  '.gov', '.edu', '.mil',
  'nature.com', 'sciencedirect.com', 'springer.com', 'wiley.com',
  'pubmed.ncbi', 'arxiv.org', 'jstor.org',
  'reuters.com', 'apnews.com', 'bbc.com', 'bbc.co.uk',
  'nytimes.com', 'wsj.com', 'economist.com',
  'hbr.org', 'mckinsey.com', 'bcg.com', 'deloitte.com',
  'gartner.com', 'forrester.com', 'statista.com'
];

const LOW_AUTHORITY_DOMAINS = [
  'reddit.com', 'twitter.com', 'x.com', 'facebook.com',
  'quora.com', 'medium.com', 'linkedin.com/pulse',
  'buzzfeed.com', 'huffpost.com',
  'ehow.com', 'wikihow.com', 'answers.com',
  'blogspot.com', 'wordpress.com'
];

// Score each citation
const scoredCitations = citations.map(url => {
  let authority = 1.0; // neutral default
  let authorityLevel = 'neutral';

  const urlLower = (url || '').toLowerCase();

  // Check high authority
  for (const domain of HIGH_AUTHORITY_DOMAINS) {
    if (urlLower.includes(domain)) {
      authority = 2.0;
      authorityLevel = 'high';
      break;
    }
  }

  // Check low authority (only if not already high)
  if (authority === 1.0) {
    for (const domain of LOW_AUTHORITY_DOMAINS) {
      if (urlLower.includes(domain)) {
        authority = 0.5;
        authorityLevel = 'low';
        break;
      }
    }
  }

  return {
    url: url,
    authority_score: authority,
    authority_level: authorityLevel
  };
});

// Calculate average authority for this query
const avgAuthority = scoredCitations.length > 0
  ? scoredCitations.reduce((sum, c) => sum + c.authority_score, 0) / scoredCitations.length
  : 1.0;

return [{
  json: {
    topic: queryData.topic,
    topic_id: queryData.topic_id,
    depth: queryData.depth,
    session_id: queryData.session_id,
    query: queryData.current_query,
    query_index: queryData.query_index,
    query_category: queryData.query_category,
    total_queries: queryData.total_queries,
    is_refinement: queryData.is_refinement,
    response: content,
    citations: scoredCitations,
    citation_count: scoredCitations.length,
    high_authority_count: scoredCitations.filter(c => c.authority_level === 'high').length,
    average_authority: avgAuthority,
    cache_hit: queryData.cache_hit,
    cached_research: queryData.cached_research,
    use_board_of_directors: queryData.use_board_of_directors,
    max_refinement_rounds: queryData.max_refinement_rounds,
    current_refinement_round: queryData.current_refinement_round,
    callback_workflow: queryData.callback_workflow,
    started_at: queryData.started_at
  }
}];

