// Process simple synthesis (non-board path)
const collectedData = $('Collect All Responses').first().json.data;
const metadata = collectedData[0];
let synthesisRaw = $('Standard Synthesis').first().json.message?.content || '{}';

// Strip markdown code blocks if present
if (synthesisRaw.startsWith('```')) {
  // Remove opening ```json or ``` and closing ```
  let cleaned = synthesisRaw;
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.slice(7);
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.slice(3);
  }
  if (cleaned.endsWith('```')) {
    cleaned = cleaned.slice(0, -3);
  }
  synthesisRaw = cleaned.trim();
}

let synthesis = {};
try {
  synthesis = typeof synthesisRaw === 'string' ? JSON.parse(synthesisRaw) : synthesisRaw;
} catch (e) {
  console.error('Synthesis parse error:', e);
  synthesis = { summary: 'Failed to synthesize', insights: [], quotes: [], statistics: [], sources: [], key_themes: [] };
}

return [{
  json: {
    topic: metadata.topic,
    topic_id: metadata.topic_id,
    depth: metadata.depth,
    session_id: metadata.session_id,
    use_board_of_directors: false,
    synthesis: synthesis,
    raw_responses: collectedData,
    cache_hit: metadata.cache_hit,
    cached_research: metadata.cached_research,
    max_refinement_rounds: metadata.max_refinement_rounds,
    current_refinement_round: metadata.current_refinement_round,
    callback_workflow: metadata.callback_workflow,
    started_at: metadata.started_at
  }
}];

// Pass through whichever input has data
const items = $input.all();
if (items.length === 0) {
  throw new Error('No input data received');
}
return items.filter(item => !item.json._empty);

// Combine synthesis with entity extraction
const synthesisData = $('Merge Synthesis Paths').first().json;
const entityRaw = $('Extract Entities & Relations').first().json.message?.content || '{}';

let entities = { entities: [], relationships: [] };
try {
  entities = typeof entityRaw === 'string' ? JSON.parse(entityRaw) : entityRaw;
} catch (e) {
  console.error('Entity parse error:', e);
}

// Calculate initial quality score
const data = synthesisData.use_board_of_directors ? synthesisData.board_perspectives : synthesisData.synthesis;
const insightCount = data?.insights?.length || 
  (synthesisData.board_perspectives?.historian?.timeline?.length || 0) +
  (synthesisData.board_perspectives?.skeptic?.criticisms?.length || 0) +
  (synthesisData.board_perspectives?.futurist?.predictions?.length || 0);

const quoteCount = data?.quotes?.length || 0;
const statCount = data?.statistics?.length || 
  (synthesisData.board_perspectives?.futurist?.market_forecasts?.length || 0);
const sourceCount = data?.sources?.length || 0;
const entityCount = entities.entities?.length || 0;

const qualityScore = Math.min(100,
  (insightCount * 4) +
  (quoteCount * 8) +
  (statCount * 6) +
  (sourceCount * 2) +
  (entityCount * 3) +
  (synthesisData.use_board_of_directors ? 15 : 0) // Bonus for board synthesis
);

return [{
  json: {
    ...synthesisData,
    entities: entities.entities || [],
    relationships: entities.relationships || [],
    quality_score: qualityScore,
    metrics: {
      insight_count: insightCount,
      quote_count: quoteCount,
      stat_count: statCount,
      source_count: sourceCount,
      entity_count: entityCount,
      relationship_count: entities.relationships?.length || 0
    }
  }
}];

// Prepare refinement loop
const currentData = $('Combine & Score').first().json;
const criticRaw = $('Critic Analysis').first().json.message?.content || '{}';

let critique = {};
try {
  critique = typeof criticRaw === 'string' ? JSON.parse(criticRaw) : criticRaw;
} catch (e) {
  console.error('Critic parse error:', e);
  critique = { follow_up_questions: [] };
}

const questions = critique.follow_up_questions || [];

if (questions.length === 0) {
  // No refinement questions, proceed to final
  return [{
    json: {
      ...currentData,
      refinement_skipped: true,
      critic_feedback: critique.quality_assessment || 'No gaps identified'
    }
  }];
}

// Prepare for refinement round
return [{
  json: {
    topic: currentData.topic,
    topic_id: currentData.topic_id,
    depth: currentData.depth,
    session_id: currentData.session_id,
    query_embedding: currentData.query_embedding || [],
    focus_areas: [],
    callback_workflow: currentData.callback_workflow,
    skip_cache: true, // Don't cache refinement queries
    current_refinement_round: currentData.current_refinement_round + 1,
    max_refinement_rounds: currentData.max_refinement_rounds,
    refinement_questions: questions,
    previous_synthesis: currentData.use_board_of_directors ? currentData.board_perspectives : currentData.synthesis,
    previous_entities: currentData.entities,
    previous_relationships: currentData.relationships,
    previous_quality_score: currentData.quality_score,
    critic_feedback: critique,
    cache_hit: false,
    cached_research: null,
    use_board_of_directors: false, // Refinement uses simple synthesis
    started_at: currentData.started_at
  }
}];

// Final assembly of research package
const data = $input.first().json;

// Determine if this came from refinement or direct path
const isRefined = data.current_refinement_round > 0 || data.refinement_skipped;

// Build final synthesis
let finalSynthesis = {};
if (data.use_board_of_directors && data.board_perspectives) {
  // Merge board perspectives into unified format
  finalSynthesis = {
    summary: [
      data.board_perspectives.historian?.evolution_summary || '',
      data.board_perspectives.skeptic?.critical_summary || '',
      data.board_perspectives.futurist?.future_summary || ''
    ].filter(s => s).join('\n\n'),
    insights: [
      ...(data.board_perspectives.historian?.timeline || []).map(t => ({text: `${t.year}: ${t.event}`, importance: 7, category: 'history'})),
      ...(data.board_perspectives.skeptic?.criticisms || []).map(c => ({text: c.point, importance: 8, category: 'warning'})),
      ...(data.board_perspectives.futurist?.predictions || []).map(p => ({text: p.prediction, importance: 8, category: 'trend'}))
    ],
    quotes: data.synthesis?.quotes || [],
    statistics: [
      ...(data.synthesis?.statistics || []),
      ...(data.board_perspectives.futurist?.market_forecasts || []).map(f => ({stat: `${f.metric}: ${f.projected} by ${f.year}`, source: 'Forecast', year: f.year}))
    ],
    sources: data.synthesis?.sources || [],
    key_themes: data.synthesis?.key_themes || [],
    board_perspectives: data.board_perspectives
  };
} else {
  finalSynthesis = data.synthesis || data.previous_synthesis || {};
}

// Merge any refinement data
if (data.previous_synthesis && data.synthesis) {
  finalSynthesis.insights = [...(data.previous_synthesis.insights || []), ...(finalSynthesis.insights || [])];
  finalSynthesis.statistics = [...(data.previous_synthesis.statistics || []), ...(finalSynthesis.statistics || [])];
  finalSynthesis.sources = [...(data.previous_synthesis.sources || []), ...(finalSynthesis.sources || [])];
}

// Deduplicate insights by text similarity
const uniqueInsights = [];
const seenInsights = new Set();
for (const insight of (finalSynthesis.insights || [])) {
  const key = insight.text?.toLowerCase().substring(0, 50);
  if (key && !seenInsights.has(key)) {
    seenInsights.add(key);
    uniqueInsights.push(insight);
  }
}
finalSynthesis.insights = uniqueInsights;

// Merge entities
const allEntities = [...(data.entities || []), ...(data.previous_entities || [])];
const uniqueEntities = [];
const seenEntities = new Set();
for (const entity of allEntities) {
  if (!seenEntities.has(entity.name)) {
    seenEntities.add(entity.name);
    uniqueEntities.push(entity);
  }
}

const allRelationships = [...(data.relationships || []), ...(data.previous_relationships || [])];

// Calculate final quality score
const finalQualityScore = Math.min(100,
  (uniqueInsights.length * 4) +
  ((finalSynthesis.quotes?.length || 0) * 8) +
  ((finalSynthesis.statistics?.length || 0) * 6) +
  ((finalSynthesis.sources?.length || 0) * 2) +
  (uniqueEntities.length * 3) +
  (data.use_board_of_directors ? 15 : 0) +
  (isRefined ? 10 : 0) // Bonus for going through refinement
);

const completedAt = new Date().toISOString();
const durationMs = new Date(completedAt) - new Date(data.started_at);

return [{
  json: {
    // Identifiers
    topic_id: data.topic_id,
    topic: data.topic,
    session_id: data.session_id,
    depth: data.depth,

    // Core research output
    summary: finalSynthesis.summary || '',
    insights: JSON.stringify(uniqueInsights),
    quotes: JSON.stringify(finalSynthesis.quotes || []),
    statistics: JSON.stringify(finalSynthesis.statistics || []),
    sources: JSON.stringify(finalSynthesis.sources || []),
    key_themes: JSON.stringify(finalSynthesis.key_themes || []),

    // Board perspectives (if used)
    board_perspectives: data.use_board_of_directors ? JSON.stringify(data.board_perspectives) : null,

    // Entity graph
    entities: JSON.stringify(uniqueEntities),
    relationships: JSON.stringify(allRelationships),

    // Quality metrics
    quality_score: finalQualityScore,
    insight_count: uniqueInsights.length,
    quote_count: finalSynthesis.quotes?.length || 0,
    stat_count: finalSynthesis.statistics?.length || 0,
    source_count: finalSynthesis.sources?.length || 0,
    entity_count: uniqueEntities.length,
    relationship_count: allRelationships.length,

    // Processing metadata
    used_board_of_directors: data.use_board_of_directors || false,
    refinement_rounds: data.current_refinement_round || 0,
    cache_hit: data.cache_hit || false,

    // Embedding for cache
    embedding: JSON.stringify(data.query_embedding || []),

    // Callback
    callback_workflow: data.callback_workflow,

    // Timing
    started_at: data.started_at,
    completed_at: completedAt,
    duration_seconds: Math.round(durationMs / 1000)
  }
}];

