// Build comprehensive response
const research = $('Final Assembly').first().json;
const savedFile = $('Save to Local File').first().json;

// Generate a unique ID based on session_id or timestamp
const researchId = research.session_id || `research_${Date.now()}`;

return [{
  json: {
    success: true,
    research_id: researchId,
    topic: research.topic,
    topic_id: research.topic_id,
    depth: research.depth,

    quality: {
      score: research.quality_score,
      grade: research.quality_score >= 80 ? 'A' : research.quality_score >= 60 ? 'B' : research.quality_score >= 40 ? 'C' : 'D'
    },

    metrics: {
      insights: research.insight_count || 0,
      quotes: research.quote_count || 0,
      statistics: research.stat_count || 0,
      sources: research.source_count || 0,
      entities: research.entity_count || 0,
      relationships: research.relationship_count || 0
    },

    processing: {
      used_board_of_directors: research.used_board_of_directors || false,
      refinement_rounds: research.refinement_rounds || 0,
      cache_hit: research.cache_hit || false,
      duration_seconds: research.duration_seconds || 0
    },

    callback_triggered: !!research.callback_workflow,

    output: {
      file_path: savedFile.file_path || savedFile.filePath,
      saved: savedFile.success || true
    }
  }
}];

